import {LEVELS,levelName,validateProfile} from './engine.js';
const $=id=>document.getElementById(id);
const titleCase=value=>value.charAt(0).toUpperCase()+value.slice(1);
let run=null, access=null, selected=null, busy=false, world=null, sound=false, audioContext=null, motionPaused=false;
const sessionKey='smartup-quest-run';
function remember(){try{if(access)sessionStorage.setItem(sessionKey,JSON.stringify(access));else sessionStorage.removeItem(sessionKey);}catch{}}
async function request(path,method='GET',data){
 const response=await fetch(path,{method,headers:{'Content-Type':'application/json','X-Smartup-Request':'1',...(access?{Authorization:`Bearer ${access.token}`}:{})},...(data?{body:JSON.stringify(data)}:{})});
 let result;try{result=await response.json();}catch{throw new Error('The challenge service is unavailable. Please try again.');}
 if(!response.ok){const error=new Error(result.error||'Please try again.');error.fields=result.fields;error.state=result.state;error.status=response.status;throw error;}return result;
}
function showError(message){$('action-error').textContent=message;$('action-error').hidden=!message;}
function sceneState(){const levels=run?.levels||LEVELS.slice(0,Number($('student-grade').value||10)-3),index=run?.levelIndex||0;
 $('journey-nodes').replaceChildren();
 levels.forEach((level,i)=>{const item=document.createElement('li'),button=document.createElement('button');button.type='button';button.textContent=levelName(level);button.dataset.marker=run?.cleared.includes(level)?'✓':i===0?'F':level;
 if(run?.cleared.includes(level))button.className='cleared';else if(i>index)button.className='locked';if(i===index)button.setAttribute('aria-current','step');button.setAttribute('aria-label',`${levelName(level)}: ${run?.cleared.includes(level)?'cleared':i===index?'current level':'locked'}`);button.addEventListener('click',()=>inspectNode(i));item.append(button);$('journey-nodes').append(item);});
 const lives=run?.lives??5;$('hearts').replaceChildren();for(let i=0;i<5;i++){const heart=document.createElement('span');heart.textContent='♥ ';if(i>=lives)heart.className='heart-spent';$('hearts').append(heart);}
 document.querySelector('.lives').setAttribute('aria-label',`${lives} of 5 lives remaining`);$('hud-level').textContent=levelName(run?.level||'foundation');$('hud-streak').replaceChildren(document.createTextNode(String(run?.streak||0)+' '));const suffix=document.createElement('span');suffix.textContent='in a row';$('hud-streak').append(suffix);
 $('journey-subject').textContent=run?`${titleCase(run.profile.subject)} · Class ${run.profile.grade}`:'YOUR NEXT DISCOVERY';
 world?.update(index,levels.length,run?.result?.proficient||false,run?.correct||0);
 inspectNode(index);
 $('question-lives').textContent=`♥ ${lives} / 5 lives`; $('question-streak').textContent=`${run?.streak||0} in a row`;
}
function inspectNode(index){const levels=run?.levels||LEVELS.slice(0,Number($('student-grade').value||10)-3);const level=levels[index];if(!level)return;$('node-inspect').textContent=run?.cleared.includes(level)?`${levelName(level)} cleared · 5 correct answers`:index===(run?.levelIndex||0)?`${levelName(level)} · ${run?.correct||0} of 5 correct`: `${levelName(level)} unlocks after ${levelName(levels[index-1])}`;}
function soundCue(kind){if(!sound)return;try{audioContext??=new AudioContext();audioContext.resume();const time=audioContext.currentTime;const notes=kind==='incorrect'?[330,294]:kind==='level-cleared'||kind==='proficient'?[523,659,784]:[523,659];notes.forEach((note,i)=>{const oscillator=audioContext.createOscillator(),gain=audioContext.createGain();oscillator.type='sine';oscillator.frequency.value=note;gain.gain.setValueAtTime(0,time+i*.1);gain.gain.linearRampToValueAtTime(.06,time+i*.1+.02);gain.gain.exponentialRampToValueAtTime(.001,time+i*.1+.25);oscillator.connect(gain);gain.connect(audioContext.destination);oscillator.start(time+i*.1);oscillator.stop(time+i*.1+.27);});}catch{}}
function setView(view){$('setup-view').hidden=view!=='setup';$('play-view').hidden=view!=='play';$('result-view').hidden=view!=='result';document.body.dataset.state=view==='play'?'playing':view;}
function renderQuestion(focus=true){setView('play');selected=null;$('question-level').textContent=levelName(run.level);$('question-subject').textContent=titleCase(run.profile.subject);$('progress-count').textContent=`${run.correct} / 5 correct`;$('level-progress').value=run.correct;$('question-topic').textContent=run.question.topic;$('question-title').textContent=run.question.prompt;$('answer-options').replaceChildren();
 run.question.options.forEach((option,i)=>{const label=document.createElement('label');label.className='answer-choice';const input=document.createElement('input');input.type='radio';input.name='answer';input.value=i;input.disabled=Boolean(run.feedback);const span=document.createElement('span'),letter=document.createElement('b');letter.textContent=String.fromCharCode(65+i);letter.setAttribute('aria-hidden','true');span.append(letter,document.createTextNode(option));label.append(input,span);input.addEventListener('change',()=>{selected=i;$('check-button').disabled=false;});if(run.feedback&&option===run.feedback.answer){label.classList.add('correct');const flag=document.createElement('small');flag.textContent='Correct';span.append(flag);}$('answer-options').append(label);});
 $('check-button').disabled=true;$('check-button').hidden=Boolean(run.feedback);$('continue-button').hidden=!run.feedback;$('answer-feedback').hidden=!run.feedback;
 if(run.feedback)renderFeedback();sceneState();if(focus){$('question-title').focus({preventScroll:true});if(matchMedia('(max-width:800px)').matches)$('challenge-panel').scrollIntoView({block:'start',behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'instant':'smooth'});}
}
function renderFeedback(){const f=run.feedback;$('answer-feedback').dataset.correct=String(f.correct);$('feedback-title').textContent=f.kind==='level-cleared'?`${levelName(run.level)} cleared!`:f.kind==='proficient'?'You reached your class level!':f.kind==='finished'?'Your learning snapshot is ready':f.correct?'That’s right!':`A little learning moment · ${run.lives} ${run.lives===1?'life':'lives'} left`;
 $('feedback-copy').textContent=f.explanation;$('continue-button').textContent=run.status==='finished'?'See my result →':f.kind==='level-cleared'?`Continue to ${levelName(run.levels[run.levelIndex+1])} →`:'Next question →';}
function renderResult(){setView('result');const result=run.result;$('result-heading').textContent=result.proficient?'Look how far you’ve come':'Your next step is clearer';$('result-person').textContent=`${run.profile.name} · Class ${run.profile.grade} · ${titleCase(run.profile.subject)}`;$('result-level').textContent=result.label;
 $('result-description').textContent=result.proficient?`You cleared every level from Foundation through Class ${run.profile.grade}. Keep building on that understanding.`:result.lastCleared===null?'Let’s strengthen the foundations together. A little focused support is a good place to begin.':`You cleared ${levelName(result.lastCleared)}. Practising ${levelName(result.failedLevel)} concepts is your next step.`;
 $('result-correct').textContent=`${result.correct} / ${result.answered}`;$('result-cleared').textContent=`${run.cleared.length} / ${run.levels.length}`;$('result-lives').textContent=`${run.lives} / 5`;$('practice-topics').replaceChildren();for(const topic of result.topicsToPractise.slice(0,5)){const li=document.createElement('li');li.textContent=topic;$('practice-topics').append(li);}$('practice-summary').hidden=!result.topicsToPractise.length;sceneState();$('result-heading').focus();}
function clearRun(){run=null;access=null;remember();selected=null;$('restart-confirm').hidden=true;$('play-view').inert=false;setView('setup');showError('');sceneState();$('student-name').focus();}
async function init(){try{await request('/api/assessment/config');$('start-button').disabled=false;$('start-button').textContent='Begin my journey ↗';$('load-status').textContent='';$('retry-load').hidden=true;try{access=JSON.parse(sessionStorage.getItem(sessionKey)||'null');}catch{access=null;}if(access){try{run=await request(`/api/assessment/runs/${access.id}`);if(run.status==='finished')renderResult();else renderQuestion(false);}catch(error){if(error.status===404){access=null;remember();}else throw error;}}}catch(error){$('load-status').textContent=error.message;$('retry-load').hidden=false;$('start-button').disabled=true;$('start-button').textContent='Challenge unavailable';}}
$('setup-form').addEventListener('submit',async event=>{event.preventDefault();if(busy)return;const data=Object.fromEntries(new FormData(event.currentTarget));data.consent=$('save-consent').checked;const errors=validateProfile(data);if(!data.consent)errors.consent='Please confirm permission to share these details.';for(const field of ['name','phone','grade','subject','consent']){const el=$(field==='consent'?'save-consent':`student-${field}`);$(`${field}-error`).textContent=errors[field]||'';el?.setAttribute('aria-invalid',String(Boolean(errors[field])));}if(Object.keys(errors).length){const first=Object.keys(errors)[0];$(first==='consent'?'save-consent':`student-${first}`)?.focus();return;}
 busy=true;$('start-button').disabled=true;$('start-button').textContent='Starting…';showError('');try{const created=await request('/api/assessment/runs','POST',data);access={id:created.id,token:created.token};remember();run=created;renderQuestion();}catch(error){showError(error.message);}finally{busy=false;$('start-button').disabled=false;$('start-button').textContent='Begin my journey ↗';}});
$('check-button').addEventListener('click',async()=>{if(busy||selected===null)return;busy=true;$('check-button').disabled=true;showError('');const chosen=selected;try{run=await request(`/api/assessment/runs/${access.id}/answer`,'POST',{questionId:run.question.id,answer:chosen});renderQuestion(false);const choice=$('answer-options').children[chosen];choice.querySelector('input').checked=true;if(!run.feedback.correct){choice.classList.add('incorrect');const flag=document.createElement('small');flag.textContent='Your answer';choice.querySelector('span').append(flag);}soundCue(run.feedback.kind);if(run.feedback.correct)world?.celebrate();$('continue-button').focus({preventScroll:true});}catch(error){if(error.state){run=error.state;renderQuestion(false);}showError(error.message);$('check-button').disabled=false;}finally{busy=false;}});
$('continue-button').addEventListener('click',async()=>{if(busy)return;if(run.status==='finished'){renderResult();return;}busy=true;$('continue-button').disabled=true;showError('');try{run=await request(`/api/assessment/runs/${access.id}/next`,'POST',{questionId:run.question.id});renderQuestion();}catch(error){if(error.state){run=error.state;renderQuestion(false);}showError(error.message);}finally{busy=false;$('continue-button').disabled=false;}});
$('retry-load').addEventListener('click',init);$('student-grade').addEventListener('change',sceneState);
$('sound-toggle').addEventListener('click',()=>{sound=!sound;$('sound-toggle').textContent=sound?'Sound on':'Sound off';$('sound-toggle').setAttribute('aria-pressed',String(sound));if(sound)soundCue('correct');});
$('motion-toggle').addEventListener('click',()=>{motionPaused=!motionPaused;world?.setPaused(motionPaused);$('motion-toggle').textContent=motionPaused?'Resume motion':'Pause motion';$('motion-toggle').setAttribute('aria-pressed',String(motionPaused));$('motion-toggle').setAttribute('aria-label',motionPaused?'Resume scene animation':'Pause scene animation');});
$('restart-button').addEventListener('click',()=>{$('restart-confirm').hidden=false;$('play-view').inert=true;$('keep-playing').focus();});$('keep-playing').addEventListener('click',()=>{$('restart-confirm').hidden=true;$('play-view').inert=false;$('restart-button').focus();});$('confirm-restart').addEventListener('click',clearRun);$('play-again').addEventListener('click',clearRun);
sceneState();init();
import('./world.js?v=quest-20260919-4').then(async module=>{world=await module.createWorld($('world'),inspectNode);document.querySelector('.world-wrap').classList.add('has-world');world.setPaused(motionPaused);sceneState();}).catch(()=>{$('world').replaceChildren();$('motion-toggle').hidden=true;});
